                '-ecapwap.header.wireless.data.ieee80211.fi.snr',
                '-ecapwap.header.wireless.data.ieee80211.fi.data_rate',
                '-ecapwap.header.wireless.data.ieee80211.dw.wlan_id_bitmap',
                '-ewlan.fc.type_subtype',
