                '-r', capture_file('cdp_coverage.pcap.gz'),
                '-Tfields', '-ecdp.deviceid', '-ecdp.portid',
                '-ecdp.voice_vlan', '-ecdp.power_requested',
                '-ecdp.power_available', '-ecdp.odr_default_gateway',
