            '6\t\t2\t1\t\t2,2,2,2,2,2,2,2',
            '7\t\t\t\t3\t2,2,2,2,2,2,2,2,2,2',
            '11\t1,2,3\t\t\t\t10,10,10,23,30,10,30,23,10',
            '13\t\t0\t0\t\t10,10',
            '14\t\t1\t2\t\t10,10,10,10,10,2,28,24',
            '15\t\t\t\t0\t10',
            '16\t\t\t\t1\t10,10,10,10',
