            'CPHAv530: FWHA_IFCONF_REQ',
            'CPHAv530: FWHA_IFCONF_REPLY',
            'CPHAv530: FWHA_IFCONF_REPLY',
            'CPHAv1501: FWHA_LB_CONF',
            'CPHAv1501: FWHA_LB_CONFIRM',
            'CPHAv2000: FWHA_POLICY_CHANGE',
            'CPHAv2000: FWHA_POLICY_CHANGE',
            'CPHAv2000: FWHA_POLICY_CHANGE',
            'CPHAv2900: FWHAP_SYNC',
