                '-r', capture_file('dcerpc_frsrpc_coverage.pcap.gz'),
                '-Y', 'dcerpc.pkt_type == 11',
                '-Tfields', '-edcerpc.drep.byteorder', '-edcerpc.cn_bind_to_uuid',
