            '1\t%s\t1\t1\t%s' % (uuid, ndr),
            '0\t%s\t1\t1\t%s' % (uuid, ndr),
            '1\t%s\t1\t1\t%s' % (uuid, ndr64),
            '1\t%s\t1\t1\t%s' % (uuid, ndr),
