            '1\t0x0002\t\tdplay 9: Enum Sessions',
            '2\t0x0002\t\tdplay 6: Enum Sessions',
            '3\t0x0001\t\tdplay 9: Enum Sessions Reply',
            '4\t0x0001\t\tdplay 6.1: Enum Sessions Reply',
