        assert rows[9][2] == '1.3.6.1.4.1.9999,1.3.6.1.4.1.9999,1.3.6.1.4.1.9999'
        assert rows[10][2].split(',')[0] == '0.0.8.450.1.1.7'
        assert rows[12][3].startswith('Undecoded INV: 1.3.6.1.4.1.1000000.3,Undecoded RES:')

